1.4 实现一个智能体
构建一个能处理分步任务的智能旅行助手。“要完成这个任务，智能体必须展现出清晰的逻辑规划能力。它需要先调用天气查询工具，并将获得的观察结果作为下一步的依据。在下一轮循环中，它再调用景点推荐工具，从而得出最终建议。

1.4.1 Step 1 安装ollama
参考: https://github.com/ollama/ollama


1.4.2 Step 2 安装一个小模型
例如安装: gemma3:12b 或者 deepseek-r1:8b


1.4.3 Step 3 准备提示词模版
设计一个“指令模板”，告诉 LLM 它应该扮演什么角色、拥有哪些工具、以及如何格式化它的思考和行动。这是我们智能体的“说明书”，它将作为system_prompt传递给 LLM。


Code
AGENT_SYSTEM_PROMPT &lt;- r"(
你是一个智能旅行助手。你的任务是分析用户的请求，并使用可用工具一步步地解决问题。

# 可用工具:
- `get_weather(city)`: 查询指定城市的实时天气。
- `get_attraction(city, weather)`: 根据城市和天气搜索推荐的旅游景点。

# 行动格式:
你的回答必须严格遵循以下格式。首先是你的思考过程，然后是你要执行的具体行动，每次回复只输出一对Thought-Action：
Thought: [这里是你的思考过程和下一步计划]
Action: 你决定采取的行动，必须是以下格式之一:
- `function_name(arg_name="arg_value")`: 调用一个可用工具。
- `Finish[最终答案]`: 当你认为已经获得最终答案时。
- 当你收集到足够的信息，能够回答用户的最终问题时，你必须在Action:字段后使用 Finish[最终答案] 来输出最终答案。

请开始吧！
)"




1.4.4 Step 4 工具函数

天气查询 使用免费的天气查询服务 wttr.in，它能以 JSON 格式返回指定城市的天气数据。



Code
library(httr)
library(jsonlite)

get_weather &lt;- function(city) {

  city_enc &lt;- URLencode(city, reserved = TRUE)
  url &lt;- paste0("https://wttr.in/", city_enc)

  tryCatch({

    res &lt;- GET(
      url,
      query = list(format = "j1", lang = "zh"),
      user_agent("weather-agent/0.1"),
      timeout(8)
    )

    stop_for_status(res)

    txt &lt;- content(res, "text", encoding = "UTF-8")

    # 🔴 关键防御：不是 JSON 直接拦截
    if (!startsWith(trimws(txt), "{")) {
      stop("返回内容不是 JSON，可能是城市名无法识别或服务异常")
    }

    data &lt;- fromJSON(txt, simplifyVector = FALSE)

    current &lt;- data$current_condition[[1]]
    desc &lt;- current$weatherDesc[[1]]$value
    temp &lt;- current$temp_C

    paste0(city, " 当前天气：", desc, "，气温 ", temp, "°C")

  }, error = function(e) {
    paste("错误：查询天气失败 -", e$message)
  })
}
get_weather("Beijing")



推荐景点查询



Code
get_attraction &lt;- function(city, weather) {

  # 1️⃣ 标准化输入
  city &lt;- trimws(city)
  weather &lt;- tolower(weather)

  # 2️⃣ 天气 → 出行类型
  scene &lt;- if (grepl("雨|snow|雪|storm", weather)) {
    "indoor"
  } else if (grepl("晴|sunny|clear", weather)) {
    "outdoor"
  } else {
    "mixed"
  }

  # 3️⃣ 内置「城市 → 景点库」
  attraction_db &lt;- list(

    "北京" = list(
      outdoor = c("颐和园", "天坛公园", "八达岭长城"),
      mixed   = c("故宫", "什刹海"),
      indoor  = c("中国国家博物馆", "中国美术馆")
    ),

    "上海" = list(
      outdoor = c("外滩", "世纪公园"),
      mixed   = c("豫园", "新天地"),
      indoor  = c("上海博物馆", "中华艺术宫")
    ),

    "长沙" = list(
      outdoor = c("岳麓山", "橘子洲头"),
      mixed   = c("太平街", "坡子街"),
      indoor  = c("湖南省博物馆")
    ),

    "杭州" = list(
      outdoor = c("西湖", "九溪十八涧"),
      mixed   = c("灵隐寺"),
      indoor  = c("浙江省博物馆")
    )
  )

  # 4️⃣ 城市容错（中英文）
  city_map &lt;- c(
    "Beijing"   = "北京",
    "Shanghai" = "上海",
    "Changsha" = "长沙",
    "Hangzhou" = "杭州"
  )

  if (city %in% names(city_map)) {
    city &lt;- city_map[[city]]
  }

  # 5️⃣ 查找城市
  if (!city %in% names(attraction_db)) {
    return(
      paste0(
        "我暂时没有 ", city,
        " 的详细景点数据。建议选择当地知名公园、博物馆或历史街区游览。"
      )
    )
  }

  # 6️⃣ 输出推荐
  recs &lt;- attraction_db[[city]][[scene]]

  paste0(
    city, " 当前天气为「", weather, "」，",
    "更适合游览【",
    ifelse(scene == "outdoor", "户外",
           ifelse(scene == "indoor", "室内", "灵活选择")),
    "景点】。\n推荐景点：",
    paste(recs, collapse = "、")
  )
}

get_attraction("Hangzhou", "Sunny")


