# HelloAgents/tools/defaults.py
from __future__ import annotations

from HelloAgents.tools.registry import ToolRegistry
from HelloAgents.tools.builtin import CalculatorTool, DateTimeTool, RegexExtractTool


def create_default_registry() -&gt; ToolRegistry:
    reg = ToolRegistry()

    # Tool 方式注册（结构化参数）
    reg.register_tool(CalculatorTool())
    reg.register_tool(DateTimeTool())
    reg.register_tool(RegexExtractTool())

